import heapq

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Implements Dijkstra's algorithm to find the shortest path in a weighted directed graph.
    Returns the shortest distance and the path taken as a list of node names.
    """
    queue = [(0, start)]
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    previous_nodes = {node: None for node in graph}

    while queue:
        current_distance, current_node = heapq.heappop(queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heapq.heappush(queue, (distance, neighbor))

    path = []
    while end is not None:
        path.append(end)
        end = previous_nodes[end]

    path.reverse()

    return (distances[path[0]], path) if distances[path[0]] < float('inf') else (float('inf'), [])

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Implements the Bellman-Ford algorithm to find the shortest path in a weighted directed graph.
    Returns the shortest distance and the path taken as a list of node names.
    """
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    predecessors = {node: None for node in graph}

    # Relax edges up to |V| - 1 times
    for _ in range(len(graph) - 1):
        for node in graph:
            for neighbor, weight in graph[node]:
                if distances[node] + weight < distances[neighbor]:
                    distances[neighbor] = distances[node] + weight
                    predecessors[neighbor] = node

    # Check for negative-weight cycles (optional, for completeness)
    for node in graph:
        for neighbor, weight in graph[node]:
            if distances[node] + weight < distances[neighbor]:
                raise ValueError("Graph contains a negative-weight cycle")

    # Reconstruct path
    path = []
    current_node = end
    while current_node is not None:
        path.append(current_node)
        current_node = predecessors[current_node]

    path.reverse()

    return (distances[end], path) if distances[end] < float('inf') else (float('inf'), [])

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Implements the Floyd-Warshall algorithm to find the shortest path in a weighted directed graph.
    This algorithm calculates the shortest paths between all pairs of nodes and then retrieves the path for the given start and end nodes.
    """
    nodes = list(graph.keys())
    dist = {node: {n: float('inf') for n in nodes} for node in nodes}
    next_node = {node: {n: None for n in nodes} for node in nodes}

    for node in nodes:
        dist[node][node] = 0

    for node in graph:
        for neighbor, weight in graph[node]:
            dist[node][neighbor] = weight
            next_node[node][neighbor] = neighbor

    for k in nodes:
        for i in nodes:
            for j in nodes:
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]
                    next_node[i][j] = next_node[i][k]

    if dist[start][end] == float('inf'):
        return (float('inf'), [])

    path = []
    while start is not None:
        path.append(start)
        start = next_node[path[-1]][end]
        if start == end:  # To prevent looping
            path.append(end)
            break

    return (dist[path[0]][end], path)

